@startuml

class Course {
  + name : string
}

class Edition {
  + numberOfParticipants : int
}

class Lesson {
  + date : date
  + startTime : time
  + duration : int
  + room : string
}

class Resource {
  + name : string
}

class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class Enrollment {
}

Course "1" -- "0..*" Edition : is offered in
Edition "1" *-- "1..*" Lesson : is organized into
Lesson "1" -- "1..*" Teacher : is given by
Course "1" -- "0..*" Teacher : has assigned
Edition "1" -- "0..*" MasterStudent : has enrolled
Edition "1" -- "0..*" ExternalAuditor : has enrolled
Edition "1" -- "0..*" Enrollment : has
MasterStudent "1" -- "0..*" Enrollment : participates
ExternalAuditor "1" -- "0..*" Enrollment : participates
Lesson "0..*" -- "0..*" Resource : requires

Course "1" -- "1" InternalTeacher : has responsible

@enduml

